/// Represents a solid hobby rocket motor (e.g. Estes, AeroTech).
pub struct SolidMotor {
    pub propellant_mass_kg: f64,
    pub dry_mass_kg: f64,
    pub burn_time_s: f64,
    pub avg_thrust_n: f64,
}

impl SolidMotor {
    /// Creates a new solid motor specification.
    pub fn new(
        propellant_mass_kg: f64,
        dry_mass_kg: f64,
        burn_time_s: f64,
        avg_thrust_n: f64,
    ) -> Self {
        Self {
            propellant_mass_kg,
            dry_mass_kg,
            burn_time_s,
            avg_thrust_n,
        }
    }

    /// Thrust generated by the motor at a given timestamp in seconds.
    pub fn thrust_at(&self, time_s: f64) -> f64 {
        if time_s >= 0.0 && time_s <= self.burn_time_s {
            self.avg_thrust_n
        } else {
            0.0
        }
    }

    /// Total mass of the motor (casing + remaining unburned propellant) at time_s.
    pub fn current_mass_at(&self, time_s: f64) -> f64 {
        if time_s <= 0.0 {
            // Motor has not fired yet, 100% fuel intact
            self.dry_mass_kg + self.propellant_mass_kg
        } else if time_s >= self.burn_time_s {
            // Propellant completely depleted, only empty casing remains
            self.dry_mass_kg
        } else {
            // Linearly burning fuel off: fraction remaining = (1.0 - time / burn_time)
            let fuel_fraction_remaining = 1.0 - (time_s / self.burn_time_s);
            self.dry_mass_kg + (self.propellant_mass_kg * fuel_fraction_remaining)
        }
    }
}
